import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputStr = scanner.next();
        StringBuilder decodedStr = new StringBuilder();
        int length = inputStr.length();

        for (int i = 0; i < length; i++) {
            if (i + 3 <= length && inputStr.substring(i, i + 3).equals("dot")) {
                decodedStr.append('.');
                i += 2;
            } else if (i + 2 <= length && inputStr.substring(i, i + 2).equals("at")) {
                decodedStr.append('@');
                i += 1;
            } else {
                decodedStr.append(inputStr.charAt(i));
            }
        }

        String result = decodedStr.toString();

        if (!result.isEmpty()) {
            if (result.charAt(0) == '.') {
                result = "dot" + result.substring(1);
            } else if (result.charAt(0) == '@') {
                result = "at" + result.substring(1);
            }
        }

        if (!result.isEmpty()) {
            if (result.charAt(result.length() - 1) == '.') {
                result = result.substring(0, result.length() - 1) + "dot";
            } else if (result.charAt(result.length() - 1) == '@') {
                result = result.substring(0, result.length() - 1) + "at";
            }
        }

        long atCount = result.chars().filter(c -> c == '@').count();

        if (atCount == 1) {
            System.out.println(result);
        } else {
            StringBuilder output = new StringBuilder();
            boolean firstAt = true;
            for (char c : result.toCharArray()) {
                if (c == '@') {
                    if (firstAt) {
                        output.append('@');
                        firstAt = false;
                    } else {
                        output.append("at");
                    }
                } else {
                    output.append(c);
                }
            }
            System.out.println(output.toString());
        }
        scanner.close();
    }
}
